integrationSettings.returnFormat:
{
  "summary": "short overall conclusion",
  "best_programs": [
    {
      "rank": 1,
      "program_name": "program",
      "division": "school",
      "why_best": "short reason",
      "student_fit": "who should consider it",
      "program_url": "url"
    }
  ],
  "email": {
    "subject": "Johns Hopkins program analysis",
    "body": "clear analysis with top programs and cautions"
  },
  "sms": "short text message under 300 characters"
}

integrationSettings.transformMapping:
summary <- {{summary}}
email_subject <- {{email.subject}}
email_body <- {{email.body}}
sms <- {{sms}}
top_program <- {{best_programs.0.program_name}}
top_reason <- {{best_programs.0.why_best}}
top_url <- {{best_programs.0.program_url}}
program_count <- {{best_programs.length}}
